# envcfg.py

import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env=None):
    if env is None:
        env = os.environ
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(tomllib.load(f))
        except FileNotFoundError:
            pass
    for key, value in env.items():
        if key.startswith(env_prefix):
            path = key[len(env_prefix):].replace('__', '.').lower()
            set_nested(config, path, coerce(value, defaults.get(path, None)))
    return config

def set_nested(d, path, value):
    keys = path.split('.')
    for key in keys[:-1]:
        if key not in d:
            d[key] = {}
        d = d[key]
    d[keys[-1]] = value

def coerce(value, default):
    if default is None:
        raise ConfigError(f'No default for {value}')
    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ['true', '1', 'yes']
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unknown type for {value}')

# test_envcfg.py

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'key': 'value'}
    config = load_config(defaults)
    assert config == {'key': 'value'}

def test_toml_file():
    defaults = {'key': 'value'}
    config = load_config(defaults, toml_path='config.toml')
    assert config == {'key': 'toml_value'}

def test_env_vars():
    defaults = {'key': 'value'}
    os.environ['APP__KEY'] = 'env_value'
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'key': 'env_value'}

def test_precedence():
    defaults = {'key': 'value'}
    os.environ['APP__KEY'] = 'env_value'
    config = load_config(defaults, toml_path='config.toml', env_prefix='APP__')
    assert config == {'key': 'env_value'}

def test_coercion():
    defaults = {'int_key': 1, 'float_key': 1.0, 'bool_key': True, 'str_key': 'string'}
    os.environ['APP__INT_KEY'] = '2'
    os.environ['APP__FLOAT_KEY'] = '2.0'
    os.environ['APP__BOOL_KEY'] = 'false'
    os.environ['APP__STR_KEY'] = 'new_string'
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'int_key': 2, 'float_key': 2.0, 'bool_key': False, 'str_key': 'new_string'}

def test_missing_default():
    defaults = {'key': 'value'}
    os.environ['APP__MISSING_KEY'] = 'env_value'
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP__')

def test_missing_toml():
    defaults = {'key': 'value'}
    config = load_config(defaults, toml_path='missing.toml')
    assert config == {'key': 'value'}
